#!/usr/bin/env python3
"""Exact verifier for Sharp Bounds for Truthful-in-Expectation Scheduling.

One file, Python 3.11+, standard library only, no network or external data.

Full fresh verification:
    python3 verify_scheduling.py --workers 2
Readable source and exact certificate inputs (no verification):
    python3 verify_scheduling.py --extract-only readable_source
Individual checks (report PARTIAL_PASS, not full acceptance):
    python3 verify_scheduling.py --only analytic
    python3 verify_scheduling.py --only rational
    python3 verify_scheduling.py --only three --workers 2

The payload below is a compressed, checksummed archive of readable Python
modules and finite mathematical inputs. It contains no recorded success
receipts and no terminal upper bounds. The default run freshly verifies all
three computational premises. The mathematical reductions and incentive
arguments are in the paper; this is not a formal proof assistant.
"""
from pathlib import Path
import argparse
import base64
import hashlib
import io
import json
import subprocess
import sys
import tempfile
import zipfile

ARCHIVE_SHA256 = "66354829d5c791c3bbae81183c1f8d60cf486be6d4f49898fbe3ab1f01a1dc0a"


def extract(destination):
    raw = base64.b85decode(b"".join(PAYLOAD.split()))
    if hashlib.sha256(raw).hexdigest() != ARCHIVE_SHA256:
        raise RuntimeError("Embedded archive integrity check failed")
    destination = destination.resolve()
    if destination.exists() and any(destination.iterdir()):
        raise RuntimeError("Use a new or empty extraction directory: " + str(destination))
    destination.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        names = archive.namelist()
        if len(names) != len(set(names)):
            raise RuntimeError("Duplicate archive paths")
        for name in names:
            path = Path(name)
            if path.is_absolute() or ".." in path.parts or "\\" in name:
                raise RuntimeError("Invalid embedded path")
            target = destination / path
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(archive.read(name))
    manifest = json.loads((destination / "MANIFEST.json").read_text())
    if set(names) != set(manifest) | {"MANIFEST.json"}:
        raise RuntimeError("Archive manifest does not cover every file")
    for name, expected in manifest.items():
        if hashlib.sha256((destination / name).read_bytes()).hexdigest() != expected:
            raise RuntimeError("Extracted-file integrity failure: " + name)
    return destination


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--workers", type=int, default=2, help="worker processes for three-machine replay (default: 2)")
    parser.add_argument("--only", choices=["all", "analytic", "rational", "three"], default="all")
    parser.add_argument("--report", type=Path, default=Path("verification_report.json"))
    parser.add_argument("--work-dir", type=Path, help="retain extracted source and generated diagnostics in a new directory")
    parser.add_argument("--extract-only", type=Path, help="extract readable source/data and exit; performs no proof verification")
    args = parser.parse_args()
    if sys.version_info < (3, 11):
        parser.error("Python 3.11 or newer is required")
    if not __debug__ or sys.flags.optimize:
        parser.error("Assertions must be enabled: do not use -O or PYTHONOPTIMIZE")
    if args.workers < 1:
        parser.error("--workers must be positive")
    if args.extract_only:
        extract(args.extract_only)
        print("EXTRACTED source and data; no certificate checks were run:", args.extract_only.resolve())
        return 0
    report = args.report.resolve()
    report.parent.mkdir(parents=True, exist_ok=True)
    report.write_text(json.dumps({"status": "RUNNING", "requested": args.only}) + "\n")
    def run(work):
        work = extract(work)
        command = [sys.executable, "-B", "-S", "-E", str(work / "run_checks.py"),
                   "--only", args.only, "--workers", str(args.workers), "--report", str(report)]
        result = subprocess.run(command, cwd=work)
        if result.returncode:
            current = json.loads(report.read_text())
            if current.get("status") not in ("FAIL", "INTERRUPTED"):
                current.update(status="FAIL", error="Verifier exited without completion")
                report.write_text(json.dumps(current, indent=2) + "\n")
            return result.returncode
        summary = json.loads(report.read_text())
        expected = "PASS" if args.only == "all" else "PARTIAL_PASS"
        if summary.get("status") != expected:
            raise RuntimeError("The child verifier did not report the requested completed checks")
        summary["embedded_archive_sha256"] = ARCHIVE_SHA256
        report.write_text(json.dumps(summary, indent=2) + "\n")
        return 0
    try:
        if args.work_dir:
            return run(args.work_dir)
        with tempfile.TemporaryDirectory(prefix="scheduling-verification-") as temporary:
            return run(Path(temporary) / "source")
    except BaseException as error:
        report.write_text(json.dumps({"status": "INTERRUPTED" if isinstance(error, KeyboardInterrupt) else "FAIL",
            "requested": args.only, "error": type(error).__name__ + ": " + str(error)}, indent=2) + "\n")
        raise


